@namespace sv_150ea48eae3b42498a3864adc1b52aa2.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }
}

@namespace sv_150ea48eae3b42498a3864adc1b52aa2.Components.Pages.Board

@if (!IsVisible)
{
    <button class="btn-add-task" @onclick="Show">Add Task</button>
}
else
{
    <div class="add-task-form">
        <input type="text" placeholder="Title" @bind="title" />
        <input type="text" placeholder="Assignee" @bind="assignee" />
        <select @bind="priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
        <input type="date" @bind="dueDate" />
        <div class="form-actions">
            <button class="btn-save" @onclick="Save">Save</button>
            <button class="btn-cancel" @onclick="Hide">Cancel</button>
        </div>
    </div>
}

@code {
    [Parameter] public EventCallback<NewTaskModel> OnTaskCreated { get; set; }

    private bool IsVisible;
    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today;

    private void Show() => IsVisible = true;

    private void Hide()
    {
        IsVisible = false;
        ResetForm();
    }

    private async Task Save()
    {
        if (!string.IsNullOrWhiteSpace(title))
        {
            await OnTaskCreated.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));
            Hide();
        }
    }

    private void ResetForm()
    {
        title = string.Empty;
        assignee = string.Empty;
        priority = "Medium";
        dueDate = DateTime.Today;
    }

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@namespace sv_150ea48eae3b42498a3864adc1b52aa2.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => MoveLeft(task)"
                      OnMoveRight="() => MoveRight(task)" />
        }
    </div>
    <div class="column-footer">
        <AddTaskForm OnTaskCreated="HandleTaskCreated" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = string.Empty;
    [Parameter, EditorRequired] public string Status { get; set; } = string.Empty;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<(TaskItem Task, string Direction)> OnTaskMoved { get; set; }
    [Parameter] public EventCallback<(string Status, AddTaskForm.NewTaskModel Model)> OnTaskCreated { get; set; }

    private async Task MoveLeft(TaskItem task)
    {
        await OnTaskMoved.InvokeAsync((task, "left"));
    }

    private async Task MoveRight(TaskItem task)
    {
        await OnTaskMoved.InvokeAsync((task, "right"));
    }

    private async Task HandleTaskCreated(AddTaskForm.NewTaskModel model)
    {
        await OnTaskCreated.InvokeAsync((Status, model));
    }
}

@namespace sv_150ea48eae3b42498a3864adc1b52aa2.Components.Pages.Board

<div class="board-stats">
    <span class="stat">Total: @Total</span>
    <span class="stat">To Do: @ToDo</span>
    <span class="stat">In Progress: @InProgress</span>
    <span class="stat">Done: @DoneCount</span>
    <span class="stat stat-overdue">Overdue: @Overdue</span>
</div>

@code {
    [Parameter] public int Total { get; set; }
    [Parameter] public int ToDo { get; set; }
    [Parameter] public int InProgress { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int Overdue { get; set; }
}

@namespace sv_150ea48eae3b42498a3864adc1b52aa2.Components.Pages.Board

<div class="board-search">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTextChanged.InvokeAsync(value);
    }
}

